window.DOCS_INDEX = [{"t": "Обзор", "u": "index.html", "g": "Введение", "x": "Квант API позволяет принимать платежи, оформлять возвраты и получать уведомления о статусах. Это REST API: ресурсы по понятным URL, ответы в JSON, стандартные HTTP-коды."}, {"t": "Базовый адрес", "p": "Обзор", "u": "index.html#base-url", "g": "Введение", "x": "Все запросы отправляются по HTTPS. Тестовая и боевая среды различаются только ключом — адрес один."}, {"t": "Быстрый старт", "p": "Обзор", "u": "index.html#quickstart", "g": "Введение", "x": "Создайте тестовый платёж на 500 ₽. Ключ sk_test_… можно скопировать в личном кабинете в разделе «Разработчикам». В ответе придёт объект платежа со статусом pending и ссылкой confirmation_url , на которую нужно перенаправить покупателя."}, {"t": "Суммы и валюты", "p": "Обзор", "u": "index.html#amounts", "g": "Введение", "x": "Суммы передаются целым числом в минимальных единицах валюты: для рублей — в копейках. 500 ₽ — это 50000 . Совет. Храните суммы в базе тоже в копейках — так не будет ошибок округления при сложении."}, {"t": "Библиотеки", "p": "Обзор", "u": "index.html#sdk", "g": "Введение", "x": "Node.js npm install @kvant/node Python pip install kvant PHP composer require kvant/kvant-php"}, {"t": "Аутентификация", "u": "auth.html", "g": "Основы", "x": "Каждый запрос подписывается секретным ключом в заголовке Authorization . Ключи бывают тестовые и боевые."}, {"t": "Типы ключей", "p": "Аутентификация", "u": "auth.html#keys", "g": "Основы", "x": "Префикс Где использовать Деньги sk_test_ Сервер, разработка и автотесты Не списываются sk_live_ Сервер, боевая среда Реальные платежи pk_live_ Браузер и мобильное приложение Только токенизация карты Важно. Секретный ключ sk_ никогда не должен попадать в браузер, мобильное приложение или публичный репозиторий."}, {"t": "Заголовок запроса", "p": "Аутентификация", "u": "auth.html#header", "g": "Основы", "x": ""}, {"t": "Ротация ключей", "p": "Аутентификация", "u": "auth.html#rotation", "g": "Основы", "x": "Создайте новый ключ, разверните его на серверах, затем отзовите старый. В течение 24 часов после отзыва старый ключ продолжает работать — это время на откат."}, {"t": "Идемпотентность", "p": "Аутентификация", "u": "auth.html#idempotency", "g": "Основы", "x": "Передавайте заголовок Idempotency-Key во всех запросах, создающих объекты. Повторный запрос с тем же ключом в течение 24 часов вернёт тот же результат и не создаст дубль."}, {"t": "Платежи", "u": "payments.html", "g": "Справочник API", "x": "Объект payment описывает одну попытку оплаты: сумму, статус, способ оплаты и ссылку для подтверждения."}, {"t": "Объект платежа", "p": "Платежи", "u": "payments.html#object", "g": "Справочник API", "x": ""}, {"t": "Статусы", "p": "Платежи", "u": "payments.html#statuses", "g": "Справочник API", "x": "pending ждёт подтверждения покупателем succeeded деньги списаны canceled отменён или истёк срок"}, {"t": "Создать платёж", "p": "Платежи", "u": "payments.html#create", "g": "Справочник API", "x": "POST /v1/payments Параметр Тип Описание amount обязательный integer Сумма в копейках, от 100. currency обязательный string Код валюты ISO 4217, например RUB . description string До 128 символов, видна покупателю. return_url string Куда вернуть покупателя после оплаты. metadata object До 20 пар ключ–значение для ваших нужд."}, {"t": "Получить платёж", "p": "Платежи", "u": "payments.html#retrieve", "g": "Справочник API", "x": "GET /v1/payments/{id}"}, {"t": "Список платежей", "p": "Платежи", "u": "payments.html#list", "g": "Справочник API", "x": "GET /v1/payments Параметр Тип Описание limit integer От 1 до 100, по умолчанию 10. starting_after string ID платежа, после которого начать — для пагинации. status string Фильтр по статусу."}, {"t": "Вернуть деньги", "p": "Платежи", "u": "payments.html#refund", "g": "Справочник API", "x": "POST /v1/payments/{id}/refunds Без amount возвращается вся сумма. Частичных возвратов может быть несколько, пока их сумма не превысит платёж."}, {"t": "Вебхуки", "u": "webhooks.html", "g": "Справочник API", "x": "Вебхуки сообщают вашему серверу о событиях: платёж прошёл, возврат выполнен, платёж отменён. Не опрашивайте API в цикле — подпишитесь на события."}, {"t": "События", "p": "Вебхуки", "u": "webhooks.html#events", "g": "Справочник API", "x": "Параметр Тип Описание payment.succeeded event Деньги списаны, заказ можно отгружать. payment.canceled event Покупатель отказался или истекло время. refund.succeeded event Возврат зачислен покупателю."}, {"t": "Тело запроса", "p": "Вебхуки", "u": "webhooks.html#payload", "g": "Справочник API", "x": ""}, {"t": "Проверка подписи", "p": "Вебхуки", "u": "webhooks.html#signature", "g": "Справочник API", "x": "Каждый запрос содержит заголовок Kvant-Signature — HMAC-SHA256 от тела запроса с вашим секретом вебхука. Проверяйте подпись до любой обработки. Сырые данные. Считайте подпись по исходным байтам тела, до парсинга JSON — иначе пробелы и порядок ключей изменят хеш."}, {"t": "Повторы", "p": "Вебхуки", "u": "webhooks.html#retries", "g": "Справочник API", "x": "Ответьте кодом 2xx в течение 10 секунд. Иначе запрос повторится через 1, 5, 30 минут, затем каждые 2 часа в течение суток. События могут прийти повторно или не по порядку — обрабатывайте их идемпотентно по id ."}, {"t": "Ошибки и лимиты", "u": "errors.html", "g": "Справочник API", "x": "API использует HTTP-коды: 2xx — успех, 4xx — ошибка в запросе, 5xx — сбой на нашей стороне."}, {"t": "Формат ошибки", "p": "Ошибки и лимиты", "u": "errors.html#format", "g": "Справочник API", "x": ""}, {"t": "Коды ответов", "p": "Ошибки и лимиты", "u": "errors.html#codes", "g": "Справочник API", "x": "Код Значение Что делать 400 Неверные параметры Смотрите поле param 401 Нет или неверный ключ Проверьте заголовок Authorization 404 Объект не найден Проверьте ID и среду (test/live) 409 Конфликт идемпотентности Тот же ключ с другими параметрами 429 Превышен лимит запросов Повторите после Retry-After 500 Ошибка сервера Повторите с тем же Idempotency-Key"}, {"t": "Лимиты запросов", "p": "Ошибки и лимиты", "u": "errors.html#limits", "g": "Справочник API", "x": "100 запросов в секунду на ключ в боевой среде и 25 — в тестовой. Текущее состояние лимита возвращается в заголовках RateLimit-Remaining и RateLimit-Reset ."}, {"t": "Повтор с задержкой", "p": "Ошибки и лимиты", "u": "errors.html#backoff", "g": "Справочник API", "x": ""}];
